mapper.select:
SELECT payment.id AS payment_id, payment.order_id, current_order.order_number, payment.toss_order_id, current_order.orderer_name, current_order.order_type, payment.amount, payment.method, payment.status, cancellation.status AS cancellation_status, cancellation.request_type AS cancellation_request_type, payment.requested_at, payment.approved_at, payment.canceled_at FROM payments AS payment INNER JOIN orders AS current_order ON current_order.id = payment.order_id LEFT JOIN payment_cancellations AS cancellation ON cancellation.id = ( SELECT MAX(recent_cancellation.id) FROM payment_cancellations AS recent_cancellation WHERE recent_cancellation.payment_id = payment.id )
WHERE payment.status = #{status}
ORDER BY payment.created_at DESC, payment.id DESC

mapper.update:
UPDATE payments
SET status = 'CANCELED',
    provider_status = #{providerStatus},
    canceled_at = #{canceledAt}
WHERE id = #{paymentId}
  AND status = 'DONE'

UPDATE payments
SET payment_key = #{paymentKey}
WHERE id = #{paymentId}
  AND status IN ('READY', 'DONE')
  AND (payment_key IS NULL OR payment_key = #{paymentKey})

UPDATE payments
SET payment_key = NULL
WHERE id = #{paymentId}
  AND status = 'READY'
  AND payment_key = #{paymentKey}

UPDATE payments
SET idempotency_key = #{idempotencyKey}
WHERE id = #{paymentId}
  AND status = 'READY'
  AND payment_key = #{paymentKey}

UPDATE payment_cancellations
SET status = 'FAILED',
    failure_code = #{failureCode},
    failure_message = #{failureMessage}
WHERE id = #{cancellationId}
  AND status = 'REQUESTED'
